"""Summary compiler (spec 8.1): summaries generated by the base model itself
(spec B.2) become each block's primary representation.

StubTruncationSummarizer exists only for CPU-bound logic tests on random-
weight models; reference runs (Modal) always use BaseModelSummarizer.
"""

from __future__ import annotations

from typing import Protocol

_SUMMARY_SYSTEM = (
    "You compress conversation or document spans for a memory system. "
    "Write a dense factual summary of the span below in at most 120 words. "
    "Preserve names, numbers, identifiers and decisions verbatim.")


class Summarizer(Protocol):
    summarizer_id: str

    def summarize(self, span_text: str) -> str: ...


class BaseModelSummarizer:
    """Summaries by the reference base model (Qwen3-4B) via the runtime's
    greedy chat loop."""

    def __init__(self, runtime, max_new_tokens: int = 192):
        self.runtime = runtime
        self.max_new_tokens = max_new_tokens
        self.summarizer_id = f"base-model:{runtime.model_id}"

    def summarize(self, span_text: str) -> str:
        messages = [
            {"role": "system", "content": _SUMMARY_SYSTEM},
            {"role": "user", "content": span_text},
        ]
        out = self.runtime.generate_text(messages, max_new_tokens=self.max_new_tokens)
        return out or span_text[:400]


class StubTruncationSummarizer:
    """Deterministic extractive stub for logic tests (no model quality
    implied). Takes the first and last sentences up to a budget."""

    summarizer_id = "stub-truncation-v1"

    def __init__(self, budget_chars: int = 400):
        self.budget_chars = budget_chars

    def summarize(self, span_text: str) -> str:
        text = " ".join(span_text.split())
        if len(text) <= self.budget_chars:
            return text
        half = self.budget_chars // 2
        return text[:half] + " ... " + text[-half:]
